"use strict";(globalThis.webpackChunksite=globalThis.webpackChunksite||[]).push([[849],{6164(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"documentationSidebar":[{"type":"link","href":"/docs/what-is-leios","label":"What is Leios","docId":"what-is-leios","unlisted":false},{"type":"link","href":"/docs/leios-use-cases","label":"Use cases","docId":"leios-use-cases","unlisted":false},{"type":"link","href":"/docs/roadmap","label":"Roadmap","docId":"roadmap","unlisted":false},{"type":"link","href":"/docs/resources","label":"Resources","docId":"resources","unlisted":false},{"type":"link","href":"/docs/monthly-reviews","label":"Monthly reviews","docId":"monthly-reviews","unlisted":false},{"type":"link","href":"/docs/faq","label":"FAQs","docId":"faq","unlisted":false},{"type":"link","href":"/docs/glossary","label":"Glossary","docId":"glossary","unlisted":false}],"developmentSidebar":[{"type":"category","label":"Research and development","items":[{"type":"link","href":"/docs/development/overview","label":"Overview","docId":"development/overview","unlisted":false},{"type":"link","href":"/docs/development/throughput-simulation","label":"Throughput simulation","docId":"development/throughput-simulation","unlisted":false},{"type":"link","href":"/docs/development/simulation-demonstration","label":"Simulation demonstration","docId":"development/simulation-demonstration","unlisted":false}],"collapsed":true,"collapsible":true}],"developmentMaterialSidebar":[{"type":"category","label":"Development","collapsed":false,"items":[{"type":"link","href":"/docs/development/status","label":"Protocol status","docId":"development/status","unlisted":false},{"type":"link","href":"/docs/parameter-graduation","label":"Parameter graduation","docId":"parameter-graduation","unlisted":false},{"type":"link","href":"/docs/development/benchmark-reports","label":"Benchmark reports","docId":"development/benchmark-reports","unlisted":false},{"type":"link","href":"/docs/development/cost-estimator","label":"Cost estimator","docId":"development/cost-estimator","unlisted":false}],"collapsible":true,"href":"/docs/development/"}],"testnetSidebar":[{"type":"category","label":"Testnet","collapsed":false,"items":[{"type":"link","href":"/docs/testnet/getting-started","label":"Install and run a node","docId":"testnet/getting-started","unlisted":false},{"type":"link","href":"/docs/testnet/register-stake-pool","label":"Register a stake pool","docId":"testnet/register-stake-pool","unlisted":false},{"type":"link","href":"/docs/testnet/rewards-program","label":"SPO Rewards Program","docId":"testnet/rewards-program","unlisted":false},{"type":"link","href":"/docs/testnet/rewards-2026-jul-sep","label":"Rewards: July to September 2026","docId":"testnet/rewards-2026-jul-sep","unlisted":false}],"collapsible":true}]},"docs":{"development/benchmark-reports":{"id":"development/benchmark-reports","title":"Benchmark reports","description":"The Performance & Tracing team benchmarks the Leios node on the same cluster that benchmarks every cardano-node release. The builds here are release candidates of the Leios node, ahead of its integration into a cardano-node release. Each run below holds the endorser-block parameters fixed and saturates them with value transactions, so a change between runs is attributable to the parameter or the build that changed.","sidebar":"developmentMaterialSidebar"},"development/cost-estimator":{"id":"development/cost-estimator","title":"Cost estimator","description":"The Linear Leios (CIP-164) cost estimator tool estimates operating costs for running a Leios node. It integrates resource usage data \u2014 CPU, disk, network egress, and IOPS \u2014 to translate confirmed transaction throughput (TxkB/s) into projected monthly expenses for stake pool operators. See the detailed cost analysis for methodology.","sidebar":"developmentMaterialSidebar"},"development/index":{"id":"development/index","title":"Development","description":"This section collects material from the ongoing development of Leios that does not fit elsewhere on this site: not the general introduction in About Leios, and not one of the interactive tools. It is a working area for results and analyses as they come out of development, so expect its contents to change as the work progresses.","sidebar":"developmentMaterialSidebar"},"development/overview":{"id":"development/overview","title":"Overview","description":"This section contains historic material from the research phase of the project. It remains a valid reference wherever it has not been superseded by material in the Development section.","sidebar":"developmentSidebar"},"development/simulation-demonstration":{"id":"development/simulation-demonstration","title":"Simulation demonstration","description":"When participants initiate a simulation, the tool displays a flow-and-stock diagram that includes epoch counts, average fees, reserves, and the treasury. These variables change according to feedback loops: higher transaction counts lead to increased fee revenue, but they also expand the ledger. Operators monitor when the cost of storing additional data exceeds the economic benefits of the increased fees. Graphs typically use colored lines or stacked areas to illustrate how each variable evolves over multiple epochs.","sidebar":"developmentSidebar"},"development/status":{"id":"development/status","title":"Protocol status","description":"{/*","sidebar":"developmentMaterialSidebar"},"development/throughput-simulation":{"id":"development/throughput-simulation","title":"Throughput simulation","description":"The throughput simulator is an interactive tool demonstrating how varying transaction volumes, ledger storage, and stake pool costs can influence Cardano\u2019s future growth. It incorporates multiple variables and feedback loops to illustrate how transaction fees and rewards circulate among the treasury, reserve, and user wallets.","sidebar":"developmentSidebar"},"faq":{"id":"faq","title":"FAQs","description":"What is Ouroboros Leios?","sidebar":"documentationSidebar"},"glossary":{"id":"glossary","title":"Glossary","description":"50% disk compression","sidebar":"documentationSidebar"},"leios-comparison":{"id":"leios-comparison","title":"Ouroboros Leios vs. Top Blockchains","description":"Cardano\u2019s upcoming Ouroboros Leios protocol promises to supercharge its scalability, targeting 100\u20131,000 transactions per second (TPS) while keeping its decentralized roots. But how does it fare against heavyweights like Solana, Ethereum, and Bitcoin, especially for use cases like microtransactions, DeFi, or voting? We\u2019ve crafted a scorecard comparing these blockchains across seven key metrics - Throughput, Fee Predictability, Fee Loss Protection, Latency, Decentralization, Security, and Scalability. With a nod to Solana\u2019s user experience (UX) struggles around fee loss, let\u2019s see why Leios could shine."},"leios-cost-analysis":{"id":"leios-cost-analysis","title":"Leios cost estimates","description":"During the April 2025 status meeting, Input Output presented preliminary cost estimates for operating nodes under the proposed Leios protocol. The following section summarizes those estimates in a structured manner, compares expected operating costs under Leios with those of the current Ouroboros Praos protocol, and outlines indicative transaction-fee revenue assumptions."},"leios-use-cases":{"id":"leios-use-cases","title":"Use cases","description":"Leios aims to increase throughput from approximately 5-10 transactions per second (TPS) to around 100 TPS, with a longer-term target of 1,000 TPS or more, subject to validation and parameter selection. This projected increase in capacity, combined with Cardano\u2019s emphasis on security, predictable fees, and a distributed network of approximately 3,000 stake pools, would expand the range of feasible use cases. The following sections outline five areas where higher throughput could have a meaningful impact.","sidebar":"documentationSidebar"},"monthly-reviews":{"id":"monthly-reviews","title":"Monthly reviews","description":"Every last Wednesday of the month, the Leios team hosts a public review meeting to share progress, foster transparency, and invite early feedback from everyone \u2013 node developers, dapp builders, SPOs, and curious community members.","sidebar":"documentationSidebar"},"parameter-graduation":{"id":"parameter-graduation","title":"Parameter graduation","description":"{/*","sidebar":"developmentMaterialSidebar"},"resources":{"id":"resources","title":"Resources","description":"This page provides a collection of resources on Ouroboros Leios, including","sidebar":"documentationSidebar"},"roadmap":{"id":"roadmap","title":"Roadmap","description":"Leios focuses on maturing a consensus protocol design from a research paper through multiple [software readiness","sidebar":"documentationSidebar"},"simple-explainer":{"id":"simple-explainer","title":"Leios - Making Cardano Faster and Ready for the Future","description":"If you\u2019re new to Cardano or curious about what\u2019s next for this blockchain, you might have heard the name Leios popping up. Don\u2019t worry if it sounds technical\u2014Leios is a project that\u2019s all about making Cardano faster, stronger, and ready for more people to use. Let\u2019s break it down in a simple way!"},"testnet/getting-started":{"id":"testnet/getting-started","title":"Install and run a node","description":"Install the Leios node, run a relay, and sync it against the public testnet.","sidebar":"testnetSidebar"},"testnet/register-stake-pool":{"id":"testnet/register-stake-pool","title":"Register a stake pool","description":"Register a Leios stake pool (block producer) on the public testnet, magic 164.","sidebar":"testnetSidebar"},"testnet/rewards-2026-jul-sep":{"id":"testnet/rewards-2026-jul-sep","title":"MusashiNet rewards: July to September 2026","description":"MusashiNet Rewards Program results for July, August and September 2026, one row per registered stake pool, with the notice and review procedure.","sidebar":"testnetSidebar"},"testnet/rewards-program":{"id":"testnet/rewards-program","title":"Musashi Testnet Rewards Program","description":"What the Musashi Testnet Rewards Program rewards stake pool operators for, how to apply, and the criteria a pool has to meet to be paid.","sidebar":"testnetSidebar"},"what-is-leios":{"id":"what-is-leios","title":"What is Leios","description":"Ouroboros Leios (Leios) is a research and development project from Input Output designed to make Cardano faster, more scalable, and ready for broader adoption. It is part of the Ouroboros family of consensus protocols, which underpin Cardano\u2019s proof-of-stake (PoS) blockchain.","sidebar":"documentationSidebar"}}}}')}}]);